contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 role, address account) public {
        // deployer (this contract) holds TIMELOCK_ADMIN_ROLE, which administers role if it is PROPOSER_ROLE
        require(role == c.PROPOSER_ROLE() || role == c.EXECUTOR_ROLE() || role == c.TIMELOCK_ADMIN_ROLE(), "need admin-controlled role");
        require(!c.hasRole(role, account), "account already has role");
        bool revertOnGrant;
        try c.grantRole(role, account) { revertOnGrant = false; } catch { revertOnGrant = true; }
        bool hasAfterGrant = c.hasRole(role, account);
        if (!revertOnGrant) {
            c.revokeRole(role, account);
        }
        bool hasAfterRevoke = c.hasRole(role, account);
        assert((revertOnGrant && !hasAfterGrant && !hasAfterRevoke) || (!revertOnGrant && hasAfterGrant && !hasAfterRevoke));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id), "already scheduled");
        uint256 minDelay = c.getMinDelay();
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert((delay >= minDelay && !reverted && c.getTimestamp(id) == block.timestamp + delay) || (delay < minDelay && reverted && !c.isOperation(id)));
    }
    receive() external payable {}
}

