contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public payable {
        // Give the test contract the proposer role (it holds TIMELOCK_ADMIN_ROLE as deployer).
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        uint256 minDelay = c.getMinDelay();
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        bool reverted;
        if (delay >= minDelay) {
            c.schedule(target, value, data, predecessor, salt, delay);
            reverted = false;
        } else {
            try c.schedule(target, value, data, predecessor, salt, delay) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 ts = c.getTimestamp(id);
        if (delay >= minDelay) {
            assert(!reverted && ts == block.timestamp + delay && c.isOperation(id) && !c.isOperationDone(id));
        } else {
            assert(reverted && ts == 0 && !c.isOperation(id));
        }
    }

    receive() external payable {}
}

