contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 extra) public {
        // The test contract holds TIMELOCK_ADMIN_ROLE (granted to deployer in C's constructor),
        // so it can grant itself the proposer role.
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        uint256 minDelay = c.getMinDelay();
        require(extra <= type(uint256).max - block.timestamp - minDelay);
        uint256 delay = minDelay + extra;
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id));
        c.schedule(target, value, data, predecessor, salt, delay);
        uint256 ts = c.getTimestamp(id);
        bool pending = c.isOperationPending(id);
        assert(ts == block.timestamp + delay && c.isOperation(id) && pending == (delay > 1));
    }
    receive() external payable {}
}

